package com.bank.bits;

// Packs account permissions into one int using bitwise operators.
class PermissionFlags {
    static final int VIEW     = 1;       // bit 0
    static final int TRANSFER = 1 << 1;  // bit 1  (left shift builds masks)
    static final int LOAN     = 1 << 2;  // bit 2
    static final int ADMIN    = 1 << 3;  // bit 3

    int set(int flags, int flag)    { return flags | flag; }          // OR sets
    int clear(int flags, int flag)  { return flags & ~flag; }         // AND with complement clears
    boolean has(int flags, int flag){ return (flags & flag) != 0; }   // AND tests
    int toggle(int flags, int flag) { return flags ^ flag; }          // XOR toggles
}
