package com.bank.bits;

// Extracts the high bits of a 32-bit hash to choose a DB shard.
class Sharder {
    private final int shardCount; // power of two, e.g. 16

    Sharder(int shardCount) { this.shardCount = shardCount; }

    // CORRECT: unsigned right shift fills zeros → always non-negative shard.
    int shardFor(int hash) {
        int shiftBits = Integer.numberOfTrailingZeros(shardCount); // log2(shardCount)
        return (hash >>> (32 - shiftBits)); // top bits, zero-filled
    }

    // BUGGY: signed right shift propagates the sign bit → negative shard.
    int shardForBuggy(int hash) {
        int shiftBits = Integer.numberOfTrailingZeros(shardCount);
        return (hash >> (32 - shiftBits)); // sign-extended → can be negative
    }

    // Overflow-safe binary-search midpoint using unsigned right shift.
    static int midpoint(int low, int high) {
        return (low + high) >>> 1; // avoids negative overflow of (low+high)/2
    }
}
