package com.bank.bits;

import java.util.logging.*;

public class BitwiseDemo {
    private static final Logger log = Logger.getLogger(BitwiseDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PermissionFlags perms = new PermissionFlags();

        // Bitwise flag manipulation.
        int flags = 0;
        flags = perms.set(flags, PermissionFlags.VIEW);
        flags = perms.set(flags, PermissionFlags.TRANSFER);
        final int afterSet = flags;
        log.info(() -> "After set VIEW|TRANSFER: " + Integer.toBinaryString(afterSet)
                + " ; has TRANSFER? " + perms.has(afterSet, PermissionFlags.TRANSFER));

        flags = perms.toggle(flags, PermissionFlags.TRANSFER); // XOR off
        final int afterToggle = flags;
        log.info(() -> "After toggle TRANSFER: " + Integer.toBinaryString(afterToggle)
                + " ; has TRANSFER? " + perms.has(afterToggle, PermissionFlags.TRANSFER));

        log.info(() -> "~VIEW (complement) = " + Integer.toBinaryString(~PermissionFlags.VIEW));

        // Shift basics.
        log.info(() -> "1 << 3 = " + (1 << 3) + " (multiply by 2^3)");
        log.info(() -> "-8 >> 1 = " + (-8 >> 1) + " (signed: keeps negative)");
        log.info(() -> "-8 >>> 28 = " + (-8 >>> 28) + " (unsigned: zero-filled, positive)");

        // Sharding: >>> correct vs >> buggy on a hash with the top bit set.
        Sharder sharder = new Sharder(16);
        int negativeHash = 0x9ABCDEF0; // top bit set → negative as signed int
        log.info(() -> "shardFor (>>>): " + sharder.shardFor(negativeHash) + " (valid 0..15)");
        log.warning(() -> "shardForBuggy (>>): " + sharder.shardForBuggy(negativeHash)
                + " (NEGATIVE → invalid partition!)");

        // Overflow-safe midpoint for binary search over huge index ranges.
        int low = 1_500_000_000, high = 2_000_000_000;
        log.info(() -> "safe midpoint (>>>): " + Sharder.midpoint(low, high)
                + " ; naive (low+high)/2 = " + ((low + high) / 2) + " (overflowed negative!)");
    }
}

